def fatorial_rec(n, prof=1):
    if n <= 1:
        return 1, prof
    valor, max_prof = fatorial_rec(n - 1, prof + 1)
    return n * valor, max_prof

def fatorial_iter(n):
    resp = 1
    for k in range(2, n + 1):
        resp *= k
    return resp, 1

print(fatorial_rec(5))
print(fatorial_iter(5))

