def busca_linear(arr, alvo):
    comparacoes = 0
    for i in range(len(arr)):
        comparacoes += 1
        if arr[i] == alvo:
            return i, comparacoes
    return -1, comparacoes

def busca_binaria(arr, alvo):
    esq, dir = 0, len(arr) - 1
    comparacoes = 0
    while esq <= dir:
        meio = (esq + dir) // 2
        comparacoes += 1
        if arr[meio] == alvo:
            return meio, comparacoes
        if arr[meio] < alvo:
            esq = meio + 1
        else:
            dir = meio - 1
    return -1, comparacoes

dados = list(range(0, 32))
print("linear:", busca_linear(dados, 31))
print("binaria:", busca_binaria(dados, 31))

