def tem_duplicado_lento(itens):
    n = len(itens)
    for i in range(n):
        for j in range(i + 1, n):
            if itens[i] == itens[j]:
                return True
    return False

print(tem_duplicado_lento([3, 7, 1, 7]))

efficiency.better:
def tem_duplicado_rapido(itens):
    vistos = set()
    for x in itens:
        if x in vistos:
            return True
        vistos.add(x)
    return False

print(tem_duplicado_rapido([3, 7, 1, 7]))
